Base x = new Derived(); Console.Write($"{x.Name()}:{((Derived)x).Name()}");
class Base { public string Name() => "base"; }
class Derived : Base { public new string Name() => "derived"; }

_ = new Child();
class Parent { public Parent() { Console.Write("B"); } }
class Child : Parent { public Child() { Console.Write("C"); } }

var c = new Counter(); ICounter boxed = c; boxed.Increment(); Console.Write($"{c.Value}:{boxed.Value}");
interface ICounter { int Value { get; } void Increment(); }
struct Counter : ICounter { public int Value { get; private set; } public void Increment() => Value++; }

Console.Write(new Label().Render());
class Label { public string Render() => "instance"; }
static class LabelExtensions { public static string Render(this Label x) => "extension"; }
